import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>
#include <math.h>

#include <cute/tensor.hpp>

using namespace cute;

constexpr int BLOCK_N        = 32;
constexpr int ROWS_PER_BLOCK = 32;
constexpr int THREADS        = ROWS_PER_BLOCK * 32;
constexpr int MAX_EPL        = 64; // supports head_dim up to 2048 (2048/32=64)

__device__ __forceinline__ int perm_idx(int i, int lane, int epl) {
  // Remap per-lane element index to reduce shared-memory bank conflicts:
  // group elements into 8-half (16-byte) chunks so that consecutive lanes
  // access consecutive chunks (matching natural vectorized coalesced access)
  // instead of each lane owning a large contiguous block with a fixed
  // 64-byte stride between lanes (which previously caused 16-way conflicts).
  int ch = ((epl & 7) == 0) ? 8 : epl;
  int blk = i / ch;
  int sub = i - blk * ch;
  return blk * (32 * ch) + lane * ch + sub;
}
__device__ __forceinline__ void cp_async_cg_16(void* smem_ptr, const void* gmem_ptr) {
  // 16-byte asynchronous copy bypassing L1 (Ampere+ cp.async.cg), used for
  // the vectorized float4-sized K/V element groups staged into shared memory.
  unsigned smem_addr = static_cast<unsigned>(__cvta_generic_to_shared(smem_ptr));
  asm volatile("cp.async.cg.shared.global [%0], [%1], %2;\n"
               :: "r"(smem_addr), "l"(gmem_ptr), "n"(16));
}
__device__ __forceinline__ void cp_async_commit_group() {
  asm volatile("cp.async.commit_group;\n");
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}
template <class TK, class TV, class TmK, class TmV>
__device__ __forceinline__ void load_kv_tile(TK &sK_t, TV &sV_t, const TmK &mK, const TmV &mV,
                                              int n0, int tile_n, int D, int tid, int nthreads) {
  // D is guaranteed divisible by 32; use 128-bit (float4) vectorized transfers
  // when possible (D % 8 == 0) to cut instruction count and improve global
  // memory transaction efficiency, falling back to half2 otherwise.
  int total_elems = tile_n * D;
  if ((D & 7) == 0) {
    int total_quads = total_elems / 8;
    for (int idx = tid; idx < total_quads; idx += nthreads) {
      int idx8 = idx * 8;
      int nn = idx8 / D;
      int dd = idx8 - nn * D;
      const float4* kptr4 = reinterpret_cast<const float4*>(&mK(n0 + nn, dd));
      const float4* vptr4 = reinterpret_cast<const float4*>(&mV(n0 + nn, dd));
      *reinterpret_cast<float4*>(&sK_t(nn, dd)) = *kptr4;
      *reinterpret_cast<float4*>(&sV_t(nn, dd)) = *vptr4;
    }
  } else {
    int total_pairs = total_elems / 2;
    for (int idx = tid; idx < total_pairs; idx += nthreads) {
      int idx2 = idx * 2;
      int nn = idx2 / D;
      int dd = idx2 - nn * D;
      const half2* kptr2 = reinterpret_cast<const half2*>(&mK(n0 + nn, dd));
      const half2* vptr2 = reinterpret_cast<const half2*>(&mV(n0 + nn, dd));
      *reinterpret_cast<half2*>(&sK_t(nn, dd)) = *kptr2;
      *reinterpret_cast<half2*>(&sV_t(nn, dd)) = *vptr2;
    }
  }
}
template <class TK, class TV, class TmK, class TmV>
__device__ __forceinline__ void load_kv_tile_async(TK &sK_t, TV &sV_t, const TmK &mK, const TmV &mV,
                                              int n0, int tile_n, int D, int tid, int nthreads) {
  // Asynchronous shared-memory staging via cp.async (Ampere+): the copy goes
  // directly from global memory to shared memory without ever occupying
  // registers, unlike the synchronous float4/half2 load-then-store path.
  // This frees registers and lets the async copy engine overlap true DMA-like
  // transfers with the ongoing softmax/PV compute on the previous tile.
  int total_elems = tile_n * D;
  if ((D & 7) == 0) {
    int total_quads = total_elems / 8;
    for (int idx = tid; idx < total_quads; idx += nthreads) {
      int idx8 = idx * 8;
      int nn = idx8 / D;
      int dd = idx8 - nn * D;
      const void* kptr4 = reinterpret_cast<const void*>(&mK(n0 + nn, dd));
      const void* vptr4 = reinterpret_cast<const void*>(&mV(n0 + nn, dd));
      void* ksmem = reinterpret_cast<void*>(&sK_t(nn, dd));
      void* vsmem = reinterpret_cast<void*>(&sV_t(nn, dd));
      cp_async_cg_16(ksmem, kptr4);
      cp_async_cg_16(vsmem, vptr4);
    }
  } else {
    // Unreachable given the D % 32 == 0 constraint enforced by the host code,
    // but kept for safety/correctness.
    load_kv_tile(sK_t, sV_t, mK, mV, n0, tile_n, D, tid, nthreads);
  }
}
template <int EPL_CT>
__global__ __launch_bounds__(THREADS)
void flash_attn_kernel(
    const half* __restrict__ Qptr,
    const half* __restrict__ Kptr,
    const half* __restrict__ Vptr,
    half*       __restrict__ Optr,
    int B, int H, int N, int D,
    float scale, int block_n)
{
  int bh = blockIdx.y;
  int h  = bh % H;
  int b  = bh / H;
  size_t bh_offset = ((size_t)b * (size_t)H + (size_t)h) * (size_t)N * (size_t)D;
  const half* Qp = Qptr + bh_offset;
  const half* Kp = Kptr + bh_offset;
  const half* Vp = Vptr + bh_offset;
  half*       Op = Optr + bh_offset;
  extern __shared__ half smem_raw[];
  half* sK_ptr0 = smem_raw;
  half* sV_ptr0 = smem_raw + (size_t)block_n * (size_t)D;
  half* sK_ptr1 = smem_raw + 2 * (size_t)block_n * (size_t)D;
  half* sV_ptr1 = smem_raw + 3 * (size_t)block_n * (size_t)D;
  auto mQ = make_tensor(make_gmem_ptr(Qp), make_shape(N, D), make_stride(D, 1));
  auto mK = make_tensor(make_gmem_ptr(Kp), make_shape(N, D), make_stride(D, 1));
  auto mV = make_tensor(make_gmem_ptr(Vp), make_shape(N, D), make_stride(D, 1));
  auto mO = make_tensor(make_gmem_ptr(Op), make_shape(N, D), make_stride(D, 1));
  auto sK_t0 = make_tensor(make_smem_ptr(sK_ptr0), make_shape(block_n, D), make_stride(D, 1));
  auto sV_t0 = make_tensor(make_smem_ptr(sV_ptr0), make_shape(block_n, D), make_stride(D, 1));
  auto sK_t1 = make_tensor(make_smem_ptr(sK_ptr1), make_shape(block_n, D), make_stride(D, 1));
  auto sV_t1 = make_tensor(make_smem_ptr(sV_ptr1), make_shape(block_n, D), make_stride(D, 1));

  int tid     = threadIdx.x;
  int warp_id = tid / 32;
  int lane    = tid % 32;
  int row     = blockIdx.x * ROWS_PER_BLOCK + warp_id;
  bool row_valid = row < N;

  constexpr int ARR_SZ = (EPL_CT > 0) ? EPL_CT : MAX_EPL;
  int epl = (EPL_CT > 0) ? EPL_CT : (D / 32); // elements-per-lane (compile-time constant when EPL_CT>0)
  alignas(16) half  q_reg[ARR_SZ];
  float o_reg[ARR_SZ];
  #pragma unroll
  for (int i = 0; i < ARR_SZ; ++i) o_reg[i] = 0.0f;
  if (row_valid) {
    int i = 0;
    for (; i + 1 < epl; i += 2) {
      const half2* qptr2 = reinterpret_cast<const half2*>(&mQ(row, perm_idx(i, lane, epl)));
      *reinterpret_cast<half2*>(&q_reg[i]) = *qptr2;
    }
    for (; i < epl; ++i) {
      q_reg[i] = mQ(row, perm_idx(i, lane, epl));
    }
  }
  float m_i = -INFINITY;
  float l_i = 0.0f;
  int first_tile_n = min(block_n, N);
  load_kv_tile_async(sK_t0, sV_t0, mK, mV, 0, first_tile_n, D, tid, THREADS);
  cp_async_commit_group();
  cp_async_wait_group<0>();
  __syncthreads();
  int stage = 0;
  for (int n0 = 0; n0 < N; n0 += block_n) {
    int tile_n = min(block_n, N - n0);
    int next_n0 = n0 + block_n;
    bool has_next = next_n0 < N;
    // Software-pipelined double buffering: prefetch the next K/V tile into the
    // other shared-memory buffer while computing on the current tile, hiding
    // global memory latency behind compute (no dependency between the two).
    if (has_next) {
      int next_tile_n = min(block_n, N - next_n0);
      if (stage == 0) load_kv_tile_async(sK_t1, sV_t1, mK, mV, next_n0, next_tile_n, D, tid, THREADS);
      else            load_kv_tile_async(sK_t0, sV_t0, mK, mV, next_n0, next_tile_n, D, tid, THREADS);
      cp_async_commit_group();
    }
    auto &sK_t = (stage == 0) ? sK_t0 : sK_t1;
    auto &sV_t = (stage == 0) ? sV_t0 : sV_t1;
    if (row_valid) {
      float s[BLOCK_N];
      #pragma unroll
      for (int nn = 0; nn < BLOCK_N; ++nn) {
        if (nn >= tile_n) { s[nn] = -INFINITY; continue; }
        float partial = 0.0f;
        int i = 0;
        if ((epl & 7) == 0) {
          for (; i < epl; i += 8) {
            float4 kv4 = *reinterpret_cast<const float4*>(&sK_t(nn, perm_idx(i, lane, epl)));
            float4 qv4 = *reinterpret_cast<const float4*>(&q_reg[i]);
            const half2* kv2 = reinterpret_cast<const half2*>(&kv4);
            const half2* qv2 = reinterpret_cast<const half2*>(&qv4);
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
              float2 kf = __half22float2(kv2[j]);
              float2 qf = __half22float2(qv2[j]);
              partial += qf.x * kf.x + qf.y * kf.y;
            }
          }
        } else {
          for (; i + 1 < epl; i += 2) {
            half2 kv = *reinterpret_cast<const half2*>(&sK_t(nn, perm_idx(i, lane, epl)));
            half2 qv = *reinterpret_cast<const half2*>(&q_reg[i]);
            float2 kf = __half22float2(kv);
            float2 qf = __half22float2(qv);
            partial += qf.x * kf.x + qf.y * kf.y;
          }
          for (; i < epl; ++i) {
            partial += __half2float(q_reg[i]) * __half2float(sK_t(nn, perm_idx(i, lane, epl)));
          }
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
          partial += __shfl_down_sync(0xffffffff, partial, offset);
        }
        partial = __shfl_sync(0xffffffff, partial, 0);
        s[nn] = partial * scale;
      }
      float tile_max = -INFINITY;
      #pragma unroll
      for (int nn = 0; nn < BLOCK_N; ++nn) {
        if (nn < tile_n) tile_max = fmaxf(tile_max, s[nn]);
      }
      float new_max = fmaxf(m_i, tile_max);
      float correction = __expf(m_i - new_max);
      l_i *= correction;
      for (int i = 0; i < epl; ++i) o_reg[i] *= correction;
      #pragma unroll
      for (int nn = 0; nn < BLOCK_N; ++nn) {
        if (nn >= tile_n) continue;
        float p = __expf(s[nn] - new_max);
        l_i += p;
        int i = 0;
        if ((epl & 7) == 0) {
          for (; i < epl; i += 8) {
            float4 vv4 = *reinterpret_cast<const float4*>(&sV_t(nn, perm_idx(i, lane, epl)));
            const half2* vv2 = reinterpret_cast<const half2*>(&vv4);
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
              float2 vf = __half22float2(vv2[j]);
              o_reg[i + 2 * j]     += p * vf.x;
              o_reg[i + 2 * j + 1] += p * vf.y;
            }
          }
        } else {
          for (; i + 1 < epl; i += 2) {
            half2 vv = *reinterpret_cast<const half2*>(&sV_t(nn, perm_idx(i, lane, epl)));
            float2 vf = __half22float2(vv);
            o_reg[i]   += p * vf.x;
            o_reg[i+1] += p * vf.y;
          }
          for (; i < epl; ++i) {
            o_reg[i] += p * __half2float(sV_t(nn, perm_idx(i, lane, epl)));
          }
        }
      }
      m_i = new_max;
    }
    if (has_next) {
      cp_async_wait_group<0>();
    }
    __syncthreads();
    stage = 1 - stage;
  }
  if (row_valid) {
    float inv_l = 1.0f / l_i;
    int i = 0;
    for (; i + 1 < epl; i += 2) {
      half2 val = __floats2half2_rn(o_reg[i] * inv_l, o_reg[i+1] * inv_l);
      *reinterpret_cast<half2*>(&mO(row, perm_idx(i, lane, epl))) = val;
    }
    for (; i < epl; ++i) {
      mO(row, perm_idx(i, lane, epl)) = __float2half(o_reg[i] * inv_l);
    }
  }
}

torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
  TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
  TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
              "Q,K,V must be float16");
  TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q,K,V must be [B,H,N,D]");

  auto Qc = Q.contiguous();
  auto Kc = K.contiguous();
  auto Vc = V.contiguous();

  int B = (int)Qc.size(0);
  int H = (int)Qc.size(1);
  int N = (int)Qc.size(2);
  int D = (int)Qc.size(3);

  TORCH_CHECK(D % 32 == 0, "embedding dimension must be divisible by 32");
  TORCH_CHECK(D / 32 <= MAX_EPL, "embedding dimension too large for this kernel");

  auto O = torch::empty_like(Qc);

  float scale = 1.0f / sqrtf((float)D);
  dim3 block(THREADS);
  dim3 grid((N + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK, B * H);
  int device_id = 0;
  cudaGetDevice(&device_id);
  int max_smem_optin = 0;
  cudaError_t attr_query_err = cudaDeviceGetAttribute(
      &max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device_id);
  TORCH_CHECK(attr_query_err == cudaSuccess,
              "cudaDeviceGetAttribute(MaxSharedMemoryPerBlockOptin) failed: ",
              cudaGetErrorString(attr_query_err));
  // Derive the largest K/V tile length (<= BLOCK_N) whose shared-memory footprint
  // (2 * block_n * D * sizeof(half)) fits within the device's actual dynamic shared
  // memory limit for this head dimension D. This preserves the tiling/online-softmax
  // structure while bounding shared memory usage across GPUs and head dims.
  size_t bytes_per_row = 4 * (size_t)D * sizeof(half);
  size_t safe_smem_limit = (size_t)max_smem_optin > 1024 ? (size_t)max_smem_optin - 1024 : (size_t)max_smem_optin;
  int block_n = BLOCK_N;
  if (bytes_per_row > 0) {
    size_t max_rows = safe_smem_limit / bytes_per_row;
    if (max_rows < (size_t)block_n) block_n = (int)max_rows;
  }
  TORCH_CHECK(block_n >= 1,
              "embedding dimension too large: cannot fit even a single K/V row (D=", D,
              ") into ", max_smem_optin, " bytes of shared memory");
  size_t smem_bytes = 4 * (size_t)block_n * (size_t)D * sizeof(half);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  int epl_dispatch = D / 32;
#define FLASH_ATTN_LAUNCH_CASE(EPLV)                                                               \
  case EPLV: {                                                                                     \
    auto attr_err = cudaFuncSetAttribute(                                                          \
        flash_attn_kernel<EPLV>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);     \
    TORCH_CHECK(attr_err == cudaSuccess,                                                           \
                "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes, " (block_n=", block_n, \
                ", D=", D, "): ", cudaGetErrorString(attr_err));                                    \
    flash_attn_kernel<EPLV><<<grid, block, smem_bytes, stream>>>(                                  \
        reinterpret_cast<const half*>(Qc.data_ptr<at::Half>()),                                    \
        reinterpret_cast<const half*>(Kc.data_ptr<at::Half>()),                                    \
        reinterpret_cast<const half*>(Vc.data_ptr<at::Half>()),                                    \
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),                                           \
        B, H, N, D, scale, block_n);                                                                \
    break;                                                                                         \
  }
  switch (epl_dispatch) {
    FLASH_ATTN_LAUNCH_CASE(1)
    FLASH_ATTN_LAUNCH_CASE(2)
    FLASH_ATTN_LAUNCH_CASE(4)
    FLASH_ATTN_LAUNCH_CASE(8)
    FLASH_ATTN_LAUNCH_CASE(16)
    FLASH_ATTN_LAUNCH_CASE(32)
    FLASH_ATTN_LAUNCH_CASE(64)
    default: {
      auto attr_err = cudaFuncSetAttribute(
          flash_attn_kernel<0>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
      TORCH_CHECK(attr_err == cudaSuccess,
                  "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes, " (block_n=", block_n,
                  ", D=", D, "): ", cudaGetErrorString(attr_err));
      flash_attn_kernel<0><<<grid, block, smem_bytes, stream>>>(
          reinterpret_cast<const half*>(Qc.data_ptr<at::Half>()),
          reinterpret_cast<const half*>(Kc.data_ptr<at::Half>()),
          reinterpret_cast<const half*>(Vc.data_ptr<at::Half>()),
          reinterpret_cast<half*>(O.data_ptr<at::Half>()),
          B, H, N, D, scale, block_n);
    }
  }
#undef FLASH_ATTN_LAUNCH_CASE
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "flash_attn_kernel launch failed: ", cudaGetErrorString(err));

  return O;
}
"""

flash_attn_ext = load_inline(
    name="cute_flash_attn_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["flash_attention_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = flash_attn_ext

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self._ext.flash_attention_forward(Q, K, V)

