  auto mK = make_tensor(make_gmem_ptr(Kp), make_shape(N, D), make_stride(D, 1));
  auto mV = make_tensor(make_gmem_ptr(Vp), make_shape(N, D), make_stride(D, 1));
  auto mO = make_tensor(make_gmem_ptr(Op), make_shape(N, D), make_stride(D, 1));
  auto sK_t0 = make_tensor(make_smem_ptr(sK_ptr0), make_shape(block_n, D), make_stride(D, 1));
  auto sV_t0 = make_tensor(make_smem_ptr(sV_ptr0), make_shape(block_n, D), make_stride(D, 1));
  auto sK_t1 = make_tensor(make_smem_ptr(sK_ptr1), make_shape(block_n, D), make_stride(D, 1));
  auto sV_t1 = make_tensor(make_smem_ptr(sV_ptr1), make_shape(block_n, D), make_stride(D, 1));

  int tid     = threadIdx.x;
  int warp_id = tid / 32;
  int lane    = tid % 32;
  int row     = blockIdx.x * ROWS_PER_BLOCK + warp_id;
  bool row_valid = row < N;

  constexpr int ARR_SZ = (EPL_CT > 0) ? EPL_CT : MAX_EPL;
  int epl = (EPL_CT > 0) ? EPL_CT : (D / 32); // elements-per-lane (compile-time constant when EPL_CT>0)
  alignas(16) half  q_reg[ARR_SZ];
  float o_reg[ARR_SZ];
  #pragma unroll
  for (int i = 0; i < ARR_SZ; ++i) o_reg[i] = 0.0f;
  if (row_valid) {
    int i = 0;
    for (; i + 1 < epl; i += 2) {
      const half2* qptr2 = reinterpret_cast<const half2*>(&mQ(row, perm_idx(i, lane, epl)));
      *reinterpret_cast<half2*>(&q_reg[i]) = *qptr2;
