  __syncthreads();
  int stage = 0;
  for (int n0 = 0; n0 < N; n0 += block_n) {
    int tile_n = min(block_n, N - n0);
    int next_n0 = n0 + block_n;
    bool has_next = next_n0 < N;
    // Software-pipelined double buffering: prefetch the next K/V tile into the
    // other shared-memory buffer while computing on the current tile, hiding
    // global memory latency behind compute (no dependency between the two).
    if (has_next) {
      int next_tile_n = min(block_n, N - next_n0);
      if (stage == 0) load_kv_tile(sK_t1, sV_t1, mK, mV, next_n0, next_tile_n, D, tid, THREADS);
      else            load_kv_tile(sK_t0, sV_t0, mK, mV, next_n0, next_tile_n, D, tid, THREADS);
    }
    auto &sK_t = (stage == 0) ? sK_t0 : sK_t1;
    auto &sV_t = (stage == 0) ? sV_t0 : sV_t1;
    if (row_valid) {
      float s[BLOCK_N];
      #pragma unroll
      for (int nn = 0; nn < BLOCK_N; ++nn) {
        if (nn >= tile_n) { s[nn] = -INFINITY; continue; }
