      float new_max = fmaxf(m_i, tile_max);
      float correction = __expf(m_i - new_max);
      l_i *= correction;
      for (int i = 0; i < epl; ++i) o_reg[i] *= correction;
      #pragma unroll
      for (int nn = 0; nn < BLOCK_N; ++nn) {
        if (nn >= tile_n) continue;
        float p = __expf(s[nn] - new_max);
        l_i += p;
        int i = 0;
        if ((epl & 7) == 0) {
          for (; i < epl; i += 8) {
            float4 vv4 = *reinterpret_cast<const float4*>(&sV_t(nn, perm_idx(i, lane, epl)));
            const half2* vv2 = reinterpret_cast<const half2*>(&vv4);
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
              float2 vf = __half22float2(vv2[j]);
              o_reg[i + 2 * j]     += p * vf.x;
              o_reg[i + 2 * j + 1] += p * vf.y;
            }
          }
        } else {
          for (; i + 1 < epl; i += 2) {
            half2 vv = *reinterpret_cast<const half2*>(&sV_t(nn, perm_idx(i, lane, epl)));
            float2 vf = __half22float2(vv);
            o_reg[i]   += p * vf.x;
            o_reg[i+1] += p * vf.y;
          }
          for (; i < epl; ++i) {
            o_reg[i] += p * __half2float(sV_t(nn, perm_idx(i, lane, epl)));
