constexpr int BLOCK_N        = 32;
constexpr int ROWS_PER_BLOCK = 32;
constexpr int THREADS        = ROWS_PER_BLOCK * 32;
constexpr int MAX_EPL        = 64; // supports head_dim up to 2048 (2048/32=64)

__device__ __forceinline__ int perm_idx(int i, int lane, int epl) {
  // Remap per-lane element index to reduce shared-memory bank conflicts:
  // group elements into 8-half (16-byte) chunks so that consecutive lanes
  // access consecutive chunks (matching natural vectorized coalesced access)
  // instead of each lane owning a large contiguous block with a fixed
  // 64-byte stride between lanes (which previously caused 16-way conflicts).
  int ch = ((epl & 7) == 0) ? 8 : epl;
  int blk = i / ch;
  int sub = i - blk * ch;
  return blk * (32 * ch) + lane * ch + sub;
}
__device__ __forceinline__ void cp_async_cg_16(void* smem_ptr, const void* gmem_ptr) {
  // 16-byte asynchronous copy bypassing L1 (Ampere+ cp.async.cg), used for
  // the vectorized float4-sized K/V element groups staged into shared memory.
  unsigned smem_addr = static_cast<unsigned>(__cvta_generic_to_shared(smem_ptr));
  asm volatile("cp.async.cg.shared.global [%0], [%1], %2;\n"
               :: "r"(smem_addr), "l"(gmem_ptr), "n"(16));
}
__device__ __forceinline__ void cp_async_commit_group() {
  asm volatile("cp.async.commit_group;\n");
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
