template <class TK, class TV, class TmK, class TmV>
__device__ __forceinline__ void load_kv_tile_async(TK &sK_t, TV &sV_t, const TmK &mK, const TmV &mV,
                                              int n0, int tile_n, int D, int tid, int nthreads) {
  // Asynchronous shared-memory staging via cp.async (Ampere+): the copy goes
  // directly from global memory to shared memory without ever occupying
  // registers, unlike the synchronous float4/half2 load-then-store path.
  // This frees registers and lets the async copy engine overlap true DMA-like
  // transfers with the ongoing softmax/PV compute on the previous tile.
  int total_elems = tile_n * D;
