      int idx8 = idx * 8;
      int nn = idx8 / D;
      int dd = idx8 - nn * D;
      const void* kptr4 = reinterpret_cast<const void*>(&mK(n0 + nn, dd));
      const void* vptr4 = reinterpret_cast<const void*>(&mV(n0 + nn, dd));
      void* ksmem = reinterpret_cast<void*>(&sK_t(nn, dd));
      void* vsmem = reinterpret_cast<void*>(&sV_t(nn, dd));
